def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not orderings:
        return []

    # Find the first element that appears in multiple orderings
    first_elements = {ordering[0] for ordering in orderings if ordering}
    for element in first_elements:
        if sum(1 for ordering in orderings if ordering and ordering[0] == element) > 1:
            break
    else:
        # No duplicates found, return the concatenation of all orderings
        result = []
        for ordering in orderings:
            result.extend(item for item in ordering if item not in result)
        return result

    # Recursively merge the orderings
    merged = []
    for ordering in orderings:
        if ordering and ordering[0] == element:
            for item in ordering:
                if item not in merged:
                    merged.append(item)
        else:
            merged.extend(item for item in ordering if item not in merged)

    return merged

