def _validate_labels(labels):
    import re
    from collections.abc import Mapping

    class ValidationError(Exception):
        def __init__(self, messages):
            self.messages = messages
            super().__init__(self._format_messages())

        def _format_messages(self):
            return "\n".join(f"{key}: {msg}" for msg_dict in self.messages for key, msg in msg_dict.items())

    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = []

    if not isinstance(labels, Mapping):
        errors.append({"labels": "expected a dictionary"})
    else:
        for key, value in labels.items():
            key_str = str(key)
            value_str = str(value)

            if not isinstance(key, (str, int, float, bool)):
                errors.append({key_str: f'expected string or bytes-like object for key'})

            if not isinstance(value, (str, int, float, bool)):
                errors.append({value_str: f'expected string or bytes-like object for value'})

            if isinstance(key, str) and not key_regex.match(key):
                errors.append({key_str: f"Label key '{key_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

            if isinstance(value, str) and not value_regex.match(value):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex '^[a-zA-Z0-9._-]+$'"})

    if errors:
        raise ValidationError(errors)

